head.script:
            scwin.onpageload = function() {

            };

            scwin.onpageunload = function() {

            };

			scwin.isWithinPercent = function(checkValue, baseValue, percentage){			
				const margin = baseValue * (percentage / 100);
				return (checkValue >= baseValue - margin) && (checkValue <= baseValue + margin);				
			}

			scwin.checkVal = function(){
				const pathData = WebSquare.wUnit.getDomById('mapchart1_map').querySelectorAll('path')[12]
				const width = 31.2;
				const height = 54.29;
				const bbox = pathData.getBBox();
				window.width = bbox.width;
				window.height = bbox.height;

				console.log('Width:', width);
				console.log('Height:', height);	
				return scwin.isWithinPercent(bbox.width, width, 2) && scwin.isWithinPercent(bbox.height, height, 2)
			}	

			scwin.unitTest = function(){
				//init
				WebSquare.wUnit.start();
				WebSquare.wUnit.addCommand("pause", "500");		
				WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
				WebSquare.wUnit.addCommand("pause", "500");		

				//Run  and stop
				WebSquare.wUnit.run();
				WebSquare.wUnit.stop();
			}
			scwin.unitTest();
